mapper.select:
SELECT coalesce(max(attempt_no), 0) + 1
FROM runrun_v2.payment_attempts
WHERE payment_order_id = #{paymentOrderId,jdbcType=BIGINT}

SELECT count(*)
FROM runrun_v2.payment_adjustments
WHERE id = #{adjustmentId,jdbcType=BIGINT}

mapper.update:
UPDATE runrun_v2.v2_orders
SET status = 'PENDING_ASSIGNMENT',
    version = version + 1,
    updated_at = #{updatedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE id = #{orderId,jdbcType=BIGINT}

mapper.select:
SELECT id::text
FROM runrun_v2.refund_orders
WHERE business_key = #{businessKey,jdbcType=VARCHAR}

SELECT order_id::text
FROM runrun_v2.payment_adjustments
WHERE id = #{adjustmentId,jdbcType=BIGINT}

SELECT status = 'PENDING_SUPPLEMENT'
FROM runrun_v2.payment_adjustments
WHERE id = #{adjustmentId,jdbcType=BIGINT}

SELECT coalesce(sum(amount_cents), 0)
FROM runrun_v2.refund_orders
WHERE source_attempt_id = #{sourceAttemptId,jdbcType=BIGINT}

SELECT credited_attempt_id::text
FROM runrun_v2.payment_orders
WHERE id = #{paymentOrderId,jdbcType=BIGINT}

mapper.update:
UPDATE runrun_v2.payment_orders
SET status = #{status,jdbcType=VARCHAR},
    version = version + 1,
    updated_at = #{updatedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE id = #{paymentOrderId,jdbcType=BIGINT}
    AND status <> #{excludedStatus,jdbcType=VARCHAR}

mapper.select:
SELECT *
FROM runrun_v2.payment_attempts
WHERE id = #{attemptId,jdbcType=BIGINT}

SELECT *
FROM runrun_v2.refund_orders
WHERE id = #{refundId,jdbcType=BIGINT}

SELECT source_attempt_id::text
FROM runrun_v2.refund_orders
WHERE id = #{refundId,jdbcType=BIGINT}

SELECT coalesce(sum(platform_cents), 0)
FROM runrun_v2.payment_financial_events
WHERE payload ->> 'sourceAttemptId' = #{sourceAttemptId,jdbcType=VARCHAR}
